mapper.select:
SELECT id, accounting_date, category_id, category_name, order_id, order_no, material_cost, material_loss_cost, mold_wear_cost, labor_cost, outsourcing_cost, other_cost, total_cost, production_quantity, unit_cost, revenue, profit, profit_margin, remark, create_time, update_time FROM cost_accounting WHERE deleted = 0
AND category_id = #{query.categoryId}
AND order_id = #{query.orderId}
AND accounting_date >= #{query.startDate}
AND accounting_date <= #{query.endDate}
ORDER BY create_time DESC
